// Источник: web-тест .qa/e2e/tests/reminders/rm-04-important-date-today-tomorrow.spec.ts, план .qa/e2e/specs/reminders.md, кейс .qa/tests/reminders/RM-04-important-date-today-tomorrow.md
// Тикет #8eab5904. Даты «сегодня/завтра» — реальные (как и в web). Создаёт запись «QA-AUTO-…» и удаляет её в конце.
// «reload» web-страницы заменён уходом в профиль и возвратом на главную (экран перечитывает данные при фокусе).
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byLabel, byLabelStartsWith, tapLabel, tapText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';

const pad = (n: number) => String(n).padStart(2, '0');
const isoDate = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const NOW = new Date();
const TODAY = isoDate(NOW);
const TOMORROW = isoDate(new Date(NOW.getFullYear(), NOW.getMonth(), NOW.getDate() + 1, 12));

async function refreshHome() {
  await toHome();
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
  await toHome();
  await (await byText('תזכורות מהירות')).waitForDisplayed({ timeout: 20000 });
}

/** Выбрать день в календаре окна; если нужный день в следующем месяце — «החודש הבא». */
async function pickDay(iso: string) {
  let day = await byLabelStartsWith(`${iso}, `);
  if (!(await day.isDisplayed().catch(() => false))) {
    await tapLabel('החודש הבא');
    day = await byLabelStartsWith(`${iso}, `);
  }
  await day.waitForDisplayed();
  await day.click();
}

async function fillName(name: string) {
  const field = await byLabel('שם התאריך');
  await field.waitForDisplayed();
  await field.clearValue();
  await field.setValue(name);
  if (await driver.isKeyboardShown().catch(() => false)) await driver.hideKeyboard().catch(() => {});
}

async function deleteQaDates() {
  await toHome();
  await (await byLabel('הוספת תאריך חשוב')).waitForDisplayed({ timeout: 20000 });
  for (let guard = 0; guard < 10; guard++) {
    const edit = await byLabelStartsWith('QA-AUTO-');
    if (!(await edit.isDisplayed().catch(() => false))) break;
    await edit.click();
    await tapLabel('מחיקת התאריך');
    await tapText('מחיקה');
    await driver.waitUntil(async () => !(await byText('מחיקה').isDisplayed().catch(() => false)));
  }
}

describe('Напоминания', () => {
  afterEach(async () => { await toHome(); });

  it('RM-04 Важная дата на сегодня / завтра появляется в «תזכורות מהירות» #8eab5904 @data', async () => {
    try {
      // 1. Главная → «+» → «תאריך חשוב» → имя «QA-AUTO-היום», день = сегодня → «הוסף תאריך».
      await toHome();
      await tapLabel('הוספת תאריך חשוב');
      await tapText('תאריך חשוב');
      await fillName('QA-AUTO-היום');
      await pickDay(TODAY);
      await tapText('הוסף תאריך');
      await expect(byText('הוסף תאריך')).not.toBeDisplayed();
      await refreshHome();
      await expect(byText('תאריך חשוב')).toBeDisplayed();
      await expect(byText('היום - QA-AUTO-היום')).toBeDisplayed();

      // 2. Карандаш → имя «QA-AUTO-מחר», день = завтра → «שמירת השינויים».
      await tapLabel('QA-AUTO-היום: פתיחה לעריכה');
      await fillName('QA-AUTO-מחר');
      await pickDay(TOMORROW);
      await tapText('שמירת השינויים');
      await expect(byText('שמירת השינויים')).not.toBeDisplayed();
      await refreshHome();
      await expect(byText('מחר - QA-AUTO-מחר')).toBeDisplayed();
      await expect(byText('היום - QA-AUTO-היום')).not.toBeDisplayed();
    } finally {
      // 3. Уборка: удалить все «QA-AUTO-…»; главная и профиль без них.
      await deleteQaDates();
      await refreshHome();
      await expect(byTextContains('QA-AUTO-')).not.toBeDisplayed();
      await toHome();
      await tapLabel('מעבר לפרטים שלי');
      await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
      await expect(byTextContains('QA-AUTO-')).not.toBeDisplayed();
    }
  });
});
